public void enableFields()
{
    FormDataSource  locFormDataSource;

    next enableFields();

    locFormDataSource = InventLocation_DS;

    // make field generally editable 
    locFormDataSource.object(fieldNum(InventLocation, DefaultReturnCreditOnlyLocation)).allowEdit(true);
}
